818	    <!-- ── Icon + Label Button ────────────────────────────────── -->
819	    <section class="section">
820	      <h2 class="section-title">Icon + Label Button</h2>
821	      <p class="section-desc">Any text button type with a leading or trailing icon. No new CSS class is needed — the gap and alignment are already handled by <code>.btn { display: inline-flex; gap: 6px; align-items: center }</code>. The only addition is a slight icon size bump.</p>
822	
823	      <div class="live-demo" style="flex-direction:column; align-items:flex-start; gap:20px;">
