825	        <div style="display:flex; flex-wrap:wrap; gap:10px; align-items:center;">
826	          <span class="size-label" style="min-width:90px;">Primary</span>
827	          <button class="btn btn-primary">
828	            <i class="bi bi-check2-circle" aria-hidden="true"></i>
829	            Save Changes
830	          </button>
831	          <button class="btn btn-primary">
832	            <i class="bi bi-send" aria-hidden="true"></i>
833	            Submit
834	          </button>
835	        </div>
836	
837	        <div style="display:flex; flex-wrap:wrap; gap:10px; align-items:center;">
838	          <span class="size-label" style="min-width:90px;">Secondary</span>
839	          <button class="btn btn-secondary">
840	            <i class="bi bi-pencil" aria-hidden="true"></i>
841	            Edit Categories
842	          </button>
843	          <button class="btn btn-secondary">
844	            <i class="bi bi-plus-lg" aria-hidden="true"></i>
845	            Add Comment
846	          </button>
847	          <button class="btn btn-secondary">
848	            <i class="bi bi-arrow-clockwise" aria-hidden="true"></i>
849	            Refresh
850	          </button>
851	        </div>
852	
853	        <div style="display:flex; flex-wrap:wrap; gap:10px; align-items:center;">
854	          <span class="size-label" style="min-width:90px;">Tertiary</span>
855	          <button class="btn btn-tertiary">
856	            <i class="bi bi-arrow-left" aria-hidden="true"></i>
857	            Back to Queue
858	          </button>
859	          <button class="btn btn-tertiary">
860	            <i class="bi bi-clock-history" aria-hidden="true"></i>
861	            View History
862	          </button>
863	        </div>
864	
865	        <div style="display:flex; flex-wrap:wrap; gap:10px; align-items:center;">
866	          <span class="size-label" style="min-width:90px;">Destructive</span>
867	          <button class="btn btn-destructive">
868	            <i class="bi bi-trash3" aria-hidden="true"></i>
869	            Delete Account
870	          </button>
871	        </div>
872	
873	        <div style="display:flex; flex-wrap:wrap; gap:10px; align-items:center;">
874	          <span class="size-label" style="min-width:90px;">Trailing icon</span>
875	          <button class="btn btn-secondary">
876	            Export
877	            <i class="bi bi-chevron-down" aria-hidden="true"></i>
878	          </button>
879	          <button class="btn btn-tertiary">
880	            Docs
881	            <i class="bi bi-box-arrow-up-right" aria-hidden="true"></i>
882	          </button>
883	          <span class="size-label">← trailing icons: dropdown chevron or external-link only</span>
884	        </div>
